import java.util.Arrays;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class CosmicCats {
    private final Set<String> catIds;

    public CosmicCats(Set<String> catIds) {
        this.catIds = ConcurrentHashMap.newKeySet(catIds);
    }

    public boolean isCosmicCat(String id) {
        return catIds.contains(id);
    }

    public String getCatIds() {
        return catIds.stream().collect(Collectors.toList()).toString();
    }

