import java.util.Arrays;
import java.util.ConcurrentModificationException;
import java.util.ImmutableSet;
import java.util.Set;
import java.util.stream.Collectors;

public class MysticMonkeys {
    private static final Set<String> MONKEY_LABELS = ImmutableSet.of("Banana", "Coco", "Mango");

    public static void main(String[] args) {
        Thread monkeyCheckerThread = new Thread(MysticMonkeys::checkMonkeyLabel);
        monkeyCheckerThread.start();

        Thread stringConverterThread = new Thread(() -> System.out.println("Monkey labels: " + getMonkeyLabelsList()));
        stringConverterThread.start();
    }

    public static boolean isMonkeyLabel(String label) {
        return MONKEY_LABELS.contains(label);
    }

    private static String getMonkeyLabelsList() {
        try {
            return Thread.currentThread().getContextClassLoader()
                    .getResource("MysticMonkeys.class")
                    .getFile()
                    .split("/")[0]
                    + ": " + MONKEY_LABELS.stream().collect(Collectors.joining(", "));
        } catch (Exception e) {
            throw new RuntimeException("Error getting resource", e);
        }
    }

    private static void checkMonkeyLabel() {
        while (true) {
            try {
                Thread.sleep(500);
            } catch (InterruptedException e) {
                // Ignore
            }

            String randomLabel = getRandomLabel();
            if (isMonkeyLabel(randomLabel)) {
                System.out.println("Found monkey label: " + randomLabel);
            } else {
                System.out.println("Did not find monkey label: " + randomLabel);
            }
        }
    }

    private static String getRandomLabel() {
        String[] labels = new String[10];
        Arrays.setAll(labels, i -> 'A' + (char) ('a' + (int) (Math.random() * 26)));
        return labels[(int) (Math.random() * 10)];
    }
}

