import java.util.stream.Collectors;

class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Point> deviceLocations;

    public DelegatingDeviceTracker(Map<String, Point> initialDevices) {
        this.deviceLocations = new ConcurrentHashMap<>(initialDevices);
    }

    public Optional<Point> getDeviceLocation(String deviceId) {
        return Optional.ofNullable(deviceLocations.get(deviceId));
    }

    public boolean setDeviceLocation(String deviceId, int x, int y) {
        Point newPoint = new Point(x, y);
        Point previousPoint = deviceLocations.putIfAbsent(deviceId, newPoint);
        return previousPoint == null || deviceLocations.replace(deviceId, previousPoint, newPoint);
    }

    public Map<String, Point> getAllDeviceLocations() {
        return Collections.unmodifiableMap(deviceLocations);
    }

    public Map<String, Point> getSnapshotOfAllDeviceLocations() {
        return deviceLocations.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, e -> new Point(e.getValue().getX(), e.getValue().getY())));
    }

    private static class UpdatePositionTask implements Runnable {
        private final DelegatingDeviceTracker tracker;
        private final String deviceId;
        private final int x;
        private final int y;

        public UpdatePositionTask(DelegatingDeviceTracker tracker, String deviceId, int x, int y) {
            this.tracker = tracker;
            this.deviceId = deviceId;
            this.x = x;
            this.y = y;
        }

        @Override
        public void run() {
            tracker.setDeviceLocation(deviceId, x, y);
        }
    }

