import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

class QuantumQuokkas {
    private static final String[] QUOKKAS = {"Zig", "Zag", "Zog"};

    public static boolean isQuokka(String label) {
        return Arrays.stream(QUOKKAS).anyMatch(label::equals);
    }

    public static String getQuokkaLabels() {
        return Arrays.stream(QUOKKAS).collect(Collectors.joining(", "));
    }
}

public class ConcurrentQuantumQuokkas {
    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            for (int i = 0; i < 10; i++) {
                System.out.println("Checking Quokka: " + Thread.currentThread().getName() + " - " + QuantumQuokkas.isQuokka("Zig"));
            }
        });

        executor.submit(() -> {
            for (int i = 0; i < 10; i++) {
                System.out.println("Getting Quokka Labels: " + Thread.currentThread().getName() + " - " + QuantumQuokkas.getQuokkaLabels());
            }
        });

        executor.shutdown();
        executor.awaitTermination(1, java.util.concurrent.TimeUnit.MINUTES);
    }
}

