import java.time.Duration;
import java.time.LocalTime;
import java.util.Random;
import java.util.concurrent.locks.ReentrantLock;

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

class ParcelCount {
    private int count;

    public ParcelCount(int initialCount) {
        this.count = initialCount;
    }

    public synchronized void addParcels(int numParcels) {
        count += numParcels;
    }

    public synchronized boolean removeParcels(int numParcels) throws NotEnoughItemsException {
        if (count >= numParcels) {
            count -= numParcels;
            return true;
        } else {
            throw new NotEnoughItemsException("Not enough parcels.");
        }
    }

    public synchronized int getCount() {
        return count;
    }
}

class Locker implements Runnable {
    private final ReentrantLock lockerLock;
    private final ParcelCount parcelCount;
    private final String name;

    public Locker(String name, ParcelCount parcelCount) {
        this.name = name;
        this.parcelCount = parcelCount;
        this.lockerLock = new ReentrantLock();
    }

    @Override
    public void run() {
        while (true) {
            tryMoveParcels(this, otherLocker, randomDelay());
        }
    }

    private void attemptMove(Locker source, Locker target, int quantity, long timeout) throws InterruptedException {
        boolean gotSourceLock = source.lockerLock.tryLock(timeout, java.util.concurrent.TimeUnit.MILLISECONDS);
        if (!gotSourceLock) {
            return;
        }

        boolean gotTargetLock = target.lockerLock.tryLock();
        if (gotTargetLock) {
            try {
                if (source.parcelCount.removeParcels(quantity)) {
                    System.out.println("Moved " + quantity + " parcels from " + source.name + " to " + target.name);
                } else {
                    throw new NotEnoughItemsException("Not enough parcels.");
                }
            } finally {
                target.lockerLock.unlock();
                source.lockerLock.unlock();
            }
        } else {
            source.lockerLock.unlock();
        }
    }

    private Locker otherLocker;
    private void tryMoveParcels(Locker source, Locker target, long timeout) {
        try {
            attemptMove(source, target, 5, timeout);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static long randomDelay() {
        return new Random().nextInt(100) + 200;
    }
}

public class DeadlockAvoidance {
    public static void main(String[] args) throws InterruptedException {
        ParcelCount locker1Parcels = new ParcelCount(20);
        ParcelCount locker2Parcels = new ParcelCount(10);

        Locker locker1 = new Locker("Locker 1", locker1Parcels);
        Locker locker2 = new Locker("Locker 2", locker2Parcels);

        otherLocker = locker2;
        ExecutorService executorService = java.util.concurrent.Executors.newFixedThreadPool(2);
        executorService.execute(locker1);
        executorService.execute(locker2);

        Thread.sleep(java.time.Duration.ofMinutes(1).toMillis());
        executorService.shutdownNow();
    }
}

