import java.time.Duration;
import java.time.LocalTime;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ReentrantLock;
import java.util.concurrent.TimeUnit;

public class DeadlockAvoidance {

    public static void main(String[] args) {
        Container c1 = new Container("Container 1");
        Container c2 = new Container("Container 2");

        for (int i = 0; i < 5; i++) {
            int finalI = i;
            Runnable task = () -> {
                try {
                    if (c1.swap(c2, finalI, Duration.ofSeconds(5), TimeUnit.SECONDS)) {
                        System.out.println("Swapped " + finalI + " elements between " + c1.getName() + " and " + c2.getName());
                    } else {
                        System.out.println("Failed to swap " + finalI + " elements between " + c1.getName() + " and " + c2.getName());
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            };
            ExecutorService executor = Executors.newFixedThreadPool(1);
            executor.execute(task);
            executor.shutdown();
        }
    }

    public static class Container {
        private final String name;
        private int elementCount;
        private final ReentrantLock lock;

        public Container(String name) {
            this.name = name;
            this.elementCount = 0;
            this.lock = new ReentrantLock();
        }

        public boolean swap(Container target, int numElements, Duration timeout, TimeUnit unit) throws InterruptedException {
            long startTime = System.nanoTime();
            boolean hasLocks = false;

            if (lock.tryLock(timeout.toNanos(unit), false)) {
                try {
                    if (target.lock.tryLock(timeout.toNanos(unit), false)) {
                        try {
                            hasLocks = true;
                            if (elementCount >= numElements) {
                                int tmp = elementCount - numElements;
                                elementCount = target.elementCount;
                                target.elementCount = tmp;
                                return true;
                            } else {
                                throw new InsufficientElementsException();
                            }
                        } finally {
                            target.lock.unlock();
                        }
                    }
                } finally {
                    lock.unlock();
                }
            }

            long elapsedTime = System.nanoTime() - startTime;
            if (!hasLocks) {
                Thread.sleep(calculateRandomDelay((long) timeout.toNanos(unit), elapsedTime));
            } else {
                Thread.sleep(calculateFixedDelay((long) timeout.toNanos(unit), elapsedTime));
            }

            return false;
        }

        public int getElementCount() {
            return elementCount;
        }

        public void setElementCount(int elementCount) {
            this.elementCount = elementCount;
        }

        public String getName() {
            return name;
        }
    }

    public static class ElementCount implements Comparable<ElementCount> {
        private final Container container;
        private final int count;

        public ElementCount(Container container, int count) {
            this.container = container;
            this.count = count;
        }

        @Override
        public int compareTo(ElementCount other) {
            return Integer.compare(this.count, other.count);
        }
    }

    public static class InsufficientElementsException extends Exception {
        public InsufficientElementsException() {
            super("Insufficient elements in the origin container");
        }
    }

    private static long calculateFixedDelay(long timeout, long elapsedTime) {
        return Math.max((timeout - elapsedTime) / 2, 0);
    }

    private static long calculateRandomDelay(long timeout, long elapsedTime) {
        return (long) (Math.random() * (timeout - elapsedTime) / 4);
    }
}

