class WidgetCount {
    private int count = 0;

    public void increment() {
        count++;
    }

    public void decrement(int num) {
        if (count >= num) {
            count -= num;
        } else {
            throw new NotEnoughWidgetsException();
        }
    }

    public int getCount() {
        return count;
    }
}

class Bin {
    private final ReentrantLock lock = new ReentrantLock();
    private final WidgetCount widgetCount = new WidgetCount();

    public void move(Bin target, int numWidgets, Duration timeout, TimeUnit unit) throws NotEnoughWidgetsException {
        long endTime = Instant.now().plus(timeout).toEpochMilli();

        if (lock.tryLock()) {
            try {
                if (target.tryLock(unit.toNanos(timeout), endTime - System.nanoTime())) {
                    try {
                        int delay = calculateDelay();
                        Thread.sleep(delay);
                        widgetCount.decrement(numWidgets);
                        target.widgetCount.increment();
                    } finally {
                        target.unlock();
                    }
                } else {
                    System.out.println("Failed to acquire target bin lock within timeout.");
                }
            } finally {
                unlock();
            }
        } else {
            System.out.println("Failed to acquire source bin lock within timeout.");
        }
    }

    public void unlock() {
        lock.unlock();
    }

    public boolean tryLock(long nanos, long endTime) {
        return lock.tryLock(nanos, endTime);
    }
}

class NotEnoughWidgetsException extends RuntimeException {
}

