import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.HashSet;
import java.util.concurrent.locks.ReentrantReadWriteLock;

class ServerStatusBeforeSplit {
    private final HashSet<String> notebooks = new HashSet<>();
    private final HashSet<String> requests = new HashSet<>();
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public void addUser(String u) {
        lock.writeLock().lock();
        try {
            notebooks.add(u);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void addQuery(String q) {
        lock.writeLock().lock();
        try {
            requests.add(q);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeUser(String u) {
        lock.writeLock().lock();
        try {
            notebooks.remove(u);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeQuery(String q) {
        lock.writeLock().lock();
        try {
            requests.remove(q);
        } finally {
            lock.writeLock().unlock();
        }
    }

    private static class Task implements Runnable {
        private final ServerStatusBeforeSplit server;
        private final String taskType;
        private final String arg;

        public Task(ServerStatusBeforeSplit server, String type, String arg) {
            this.server = server;
            this.taskType = type;
            this.arg = arg;
        }

        @Override
        public void run() {
            switch (taskType) {
                case "addUser":
                    server.addUser(arg);
                    break;
                case "addQuery":
                    server.addQuery(arg);
                    break;
                case "removeUser":
                    server.removeUser(arg);
                    break;
                case "removeQuery":
                    server.removeQuery(arg);
                    break;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 10; i++) {
            String taskType = "addUser";
            if (i % 3 == 0) taskType = "removeUser";
            if (i % 7 == 0) taskType = "addQuery";
            if (i % 5 == 0) taskType = "removeQuery";
            executor.execute(new Task(server, taskType, String.valueOf(i)));
        }

        executor.shutdown();
        executor.awaitTermination(1, java.util.concurrent.TimeUnit.HOURS);
    }
}

