    private final SafePoint location;

    public VehicleCoordinate(String vehicleId, SafePoint location) {
        this.vehicleId = Objects.requireNonNull(vehicleId);
        this.location = Objects.requireNonNull(location);
    }

    public String getVehicleId() {
        return vehicleId;
    }

    public SafePoint getLocation() {
        return location;
    }
