class PublishingVehicleTracker {
    private final Map<String, SafePoint> coordinates;
    private final Map<String, VehicleCoordinate> vehicleCoordinates;

    public PublishingVehicleTracker() {
        this.coordinates = new ConcurrentHashMap<>();
        this.vehicleCoordinates = Collections.synchronizedMap(new HashMap<>());
    }

    public void updateVehicleCoordinate(String vehicleId, double newX, double newY) {
        Objects.requireNonNull(vehicleId);
        SafePoint updatedLocation = new SafePoint(newX, newY);

        while (true) {
            VehicleCoordinate currentVehicleCoordinate = vehicleCoordinates.get(vehicleId);
            if (currentVehicleCoordinate == null || currentVehicleCoordinate.getLocation().equals(updatedLocation)) {
                break;
            }

            // If the vehicle's location has not changed, do nothing and retry.
        }

        coordinates.put(vehicleId, updatedLocation);
        vehicleCoordinates.put(vehicleId, new VehicleCoordinate(vehicleId, updatedLocation));
    }

    public SafePoint getVehicleCoordinate(String vehicleId) {
        Objects.requireNonNull(vehicleId);
        VehicleCoordinate vehicleCoordinate = vehicleCoordinates.get(vehicleId);
        return (vehicleCoordinate == null) ? null : vehicleCoordinate.getLocation();
    }

    public Map<String, SafePoint> getAllVehicleCoordinates() {
        return Collections.unmodifiableMap(coordinates);
    }
}

