import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Function;
import java.util.stream.Collectors;

class SafePoint {
    final int x, y;

    SafePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SafePoint)) return false;
        SafePoint safePoint = (SafePoint) o;
        return x == safePoint.x && y == safePoint.y;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}

class VehiclePosition {
    final String id;
    final SafePoint point;

    VehiclePosition(String id, SafePoint point) {
        this.id = id;
        this.point = point;
    }
}

class PublishingVehicleTracker {
    private final Map<String, SafePoint> positions;
    private final AtomicReference<Map<String, SafePoint>> publishedPositions;

    public PublishingVehicleTracker() {
        this.positions = new HashMap<>();
        this.publishedPositions = new AtomicReference<>(Map.of());
    }

    public Map<String, SafePoint> getPositions() {
        return publishedPositions.get();
    }

    public SafePoint getPosition(String id) {
        return positions.get(id);
    }

    public void setPosition(String id, int x, int y) {
        var updatedPosition = new SafePoint(x, y);
        var previousValue = new HashMap<String, SafePoint>();

        while (!positions.putIfAbsent(id, updatedPosition) == null ||
                !positions.replace(id, previousValue.put(id, updatedPosition), updatedPosition)) {
            previousValue = positions.get(id);
        }

        var publishedPositionsSnapshot = publishedPositions.get();
        var newPublishedPositions = new HashMap<>(publishedPositionsSnapshot);

        if (newPublishedPositions.merge(id, updatedPosition, (oldVal, newVal) -> newVal).equals(previousValue.get(id))) {
            while (!publishedPositions.compareAndSet(publishedPositionsSnapshot, newPublishedPositions)) {
                publishedPositionsSnapshot = publishedPositions.get();
                newPublishedPositions = new HashMap<>(publishedPositionsSnapshot);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        var tracker = new PublishingVehicleTracker();
        var executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 10; i++) {
            final int index = i;
            Runnable task = () -> {
                try {
                    TimeUnit.MILLISECONDS.sleep(ThreadLocalRandom.current().nextInt(50, 500));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                tracker.setPosition("Vehicle-" + index, index * 10, index * 10);
            };
            executor.submit(task);
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);

        System.out.println("Final vehicle positions:");
        var groupedByThread = tracker.getPositions().values()
                .stream()
                .collect(Collectors.groupingBy(Function.identity(), HashMap::new, Collectors.counting()));

        for (Map.Entry<SafePoint, Long> entry : groupedByThread.entrySet()) {
            System.out.printf("(%d, %d) -> %s%n", entry.getKey().x, entry.getKey().y, entry.getValue());
        }
    }
}

