import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Fungloon {
    public final int flint;
    public final int drizzle;

    public Fungloon(int flint, int drizzle) {
        this.flint = flint;
        this.drizzle = drizzle;
    }
}

class FungloonGenerator implements Runnable {
    private final int bound;
    private Fungloon[] fungloons;

    public FungloonGenerator(int bound, int numFungloons) {
        this.bound = bound;
        this.fungloons = new Fungloon[numFungloons];
    }

    @Override
    public void run() {
        for (int i = 0; i < fungloons.length; i++) {
            fungloons[i] = new Fungloon(randomInt(), randomInt());
        }
    }

    private int randomInt() {
        return ThreadLocalRandom.current().nextInt(0, bound);
    }

    public Fungloon[] getFungloons() {
        return fungloons;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(5);
        FungloonGenerator generator1 = new FungloonGenerator(100, 10);
        FungloonGenerator generator2 = new FungloonGenerator(100, 10);

        executor.submit(generator1);
        executor.submit(generator2);

        executor.shutdown();
        executor.awaitTermination(1, java.util.concurrent.TimeUnit.MINUTES);

        Fungloon[] fungloons1 = generator1.getFungloons();
