            }
        }
    }

    private static Weaver[] getWeaversFromExecutor(ExecutorService executor) {
        java.util.List<Weaver> weavers = executor.unwrap().getQueue().stream()
                .filter(task -> task instanceof Weaver)
                .map(task -> (Weaver) task)
                .collect(java.util.Collectors.toList());
        return weavers.toArray(new Weaver[0]);
    }
}

