import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.Map;
import java.util.Collections;
import java.util.concurrent.ConcurrentMap;

public class MysticBeastTracker {
    private final ConcurrentMap<String, Glyph> perches;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        this.perches = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    public Glyph getPerch(String sigil) {
        return perches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        if (perches.putIfAbsent(sigil, new Glyph(spark, glimmer)) != null) {
            throw new IllegalArgumentException("Beast already exists.");
        } else {
            perches.computeIfPresent(sigil, (k, v) -> new Glyph(spark, glimmer));
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(perches));
    }

    private static class Glyph {
        final int spark;
        final int glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }
    }

    private static class TransmuteTask implements Runnable {
        private final ConcurrentMap<String, Glyph> perches;
        private final String sigil;
        private final int spark;
        private final int glimmer;

        public TransmuteTask(ConcurrentMap<String, Glyph> perches, String sigil, int spark, int glimmer) {
            this.perches = perches;
            this.sigil = sigil;
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public void run() {
            perches.computeIfPresent(sigil, (k, v) -> new Glyph(spark, glimmer));
        }
    }

    private static class RandomTask implements Runnable {
        private final ConcurrentMap<String, Glyph> perches;

        public RandomTask(ConcurrentMap<String, Glyph> perches) {
            this.perches = perches;
        }

        @Override
        public void run() {
            String randomSigil = ThreadLocalRandom.current().nextInt(100, 999) + "";
            if (perches.putIfAbsent(randomSigil, new Glyph(ThreadLocalRandom.current().nextInt(), ThreadLocalRandom.current().nextInt())) != null) {
                perches.computeIfPresent(randomSigil, (k, v) -> new Glyph(ThreadLocalRandom.current().nextInt(), ThreadLocalRandom.current().nextInt()));
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentMap<String, MysticBeastTracker.Glyph> initialPerches = new ConcurrentHashMap<>();
        initialPerches.put("S1", new MysticBeastTracker.Glyph(0, 0));
        MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);

        ExecutorService executorService = Executors.newFixedThreadPool(5);
        for (int i = 0; i < 10; i++) {
