            Runnable task = () -> tracker.setPerch("S" + finalI, finalI, finalI * finalI);
            executorService.execute(task);
        }

        RandomTask randomTask = new RandomTask(tracker.perches);
        executorService.execute(randomTask);
        executorService.execute(randomTask);

        TransmuteTask transmuteTask1 = new TransmuteTask(tracker.perches, "S4", 33, 66);
        executorService.execute(transmuteTask1);

        executorService.shutdown();
        executorService.awaitTermination(Long.MAX_VALUE, java.util.concurrent.TimeUnit.NANOSECONDS);

        System.out.println("Current perches: " + tracker.getPerches());
    }
}

