import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.*;

interface Talisman {
    int enchant();
}

interface SigilNode<T extends SigilNode<T, S>, S extends SigilNode<T, S>> {
    List<S> getChildren();

    default int enchant() {
        if (getChildren().isEmpty()) {
            return ((Talisman) this).enchant();
        } else {
            ExecutorService executor = Executors.newFixedThreadPool(2);
            List<Future<Integer>> futures = new ArrayList<>();

            for (SigilNode child : getChildren()) {
                futures.add(executor.submit(() -> child.enchant()));
            }

            int result = 0;
            try {
                for (Future<Integer> future : futures) {
                    result += future.get();
