import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ConcurrentSpellcasting {

    public interface Charm<T> {
        T execute() throws Exception;
    }

    public interface RuneNode<R extends RuneNode<R, T>, T> {
        List<R> getChildren();

        T accept(RuneVisitor<R, T> visitor) throws Exception;

        default void forEachChild(Consumer<R> consumer) {
            getChildren().forEach(consumer);
        }
    }

    public interface RuneVisitor<R extends RuneNode<?, T>, T> {
        T visit(R rune) throws Exception;
    }

    private static class SequentialCharmProcessor<T> implements Charm<T> {
        private final RuneNode<?, T> root;

        public SequentialCharmProcessor(RuneNode<?, T> root) {
            this.root = root;
        }

        @Override
        public T execute() throws Exception {
            return root.accept(new RuneVisitor<RuneNode<?, T>, T>() {
                private T accumulator = null;

                @Override
                public T visit(RuneNode<?, T> rune) throws Exception {
                    if (acculator == null) {
                        acculator = rune.execute();
                    } else {
                        acculator = rune.combine(acculator);
                    }
                    return acculator;
                }
            });
        }
    }

    private static class ParallelCharmProcessor<T> implements Charm<T> {
        private final RuneNode<?, T> root;
        private final ExecutorService executor;

        public ParallelCharmProcessor(RuneNode<?, T> root) {
            this.root = root;
            this.executor = Executors.newFixedThreadPool(2); // Limit to 2 additional threads
        }

        @Override
        public T execute() throws Exception {
            List<Future<T>> futures = new ArrayList<>();
            root.forEachChild(rune -> futures.add(executor.submit(() -> {
                try {
                    return rune.execute();
                } catch (Exception e) {
                    throw new CompletionException(e);
                }
            })));

            T accumulator = root.getInitialValue();
            for (Future<T> future : futures) {
                accumulator = root.combine(accumulator, future.get());
            }

            executor.shutdown();
            return accumulator;
        }
    }

    private static class RecursiveRuneVisitor<R extends RuneNode<R, T>, T> implements RuneVisitor<R, T> {
        private final RuneVisitor<R, T> visitor;

        public RecursiveRuneVisitor(RuneVisitor<R, T> visitor) {
            this.visitor = visitor;
        }

        @Override
        public T visit(R rune) throws Exception {
            if (!rune.getChildren().isEmpty()) {
                List<R> children = new ArrayList<>(rune.getChildren());
                T accumulator = rune.getInitialValue();
                for (R child : children) {
                    accumulator = child.accept(this);
                }
                return rune.combine(accumulator);
            } else {
                return visitor.visit(rune);
            }
        }
    }

    private static class RecursiveRuneNode<R extends RuneNode<R, T>, T> implements RuneNode<R, T> {
        private final RuneNode<?, T> node;
        private List<R> children = new ArrayList<>();

        public RecursiveRuneNode(RuneNode<?, T> node) {
            this.node = node;
        }

        @Override
        public List<R> getChildren() {
            return children;
        }

        @Override
        public T accept(RuneVisitor<R, T> visitor) throws Exception {
            if (children.isEmpty()) {
                children = node.getChildren().stream().map(RuneNode::new).collect(Collectors.toList());
            }
            return new RecursiveRuneVisitor<>(visitor).visit(this);
        }

        @Override
        public T execute() throws Exception {
            return accept(visitor -> visitor.visit(node));
        }

        @Override
        public T getInitialValue() {
            return node.getInitialValue();
        }

        @Override
        public T combine(T a, T b) {
            return node.combine(a, b);
        }
    }

    public static <T> Charm<T> sequentialCharmProcessor(RuneNode<?, T> root) {
        return new SequentialCharmProcessor<>(root);
    }

    public static <T> Charm<T> parallelCharmProcessor(RuneNode<?, T> root) {
        return new ParallelCharmProcessor<>(root);
    }

    public static <R extends RuneNode<R, T>, T> R createRecursiveRuneNode(RuneNode<?, T> node) {
        return new RecursiveRuneNode<>(node);
    }

    public static void main(String[] args) throws Exception {
        // Example usage:
        RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<LeafRune, Integer>>, Integer>>, Integer>>, Integer>>, Integer>, Integer> root = new LeafRune(1);
