        RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<RuneNode<RecursiveRuneNode<LeafRune, Integer>>, Integer>>, Integer>>, Integer> thirdLevel = new LeafRune(3);
        root.getChildren().add(new RecursiveRuneNode<>(secondLevel));
        secondLevel.getChildren().add(new RecursiveRuneNode<>(thirdLevel));
        thirdLevel.getChildren().add(new RecursiveRuneNode<>(root));

        Charm<Integer> sequentialProcessor = sequentialCharmProcessor(root);
        Charm<Integer> parallelProcessor = parallelCharmProcessor(createRecursiveRuneNode(root));

        System.out.println("Sequential result: " + sequentialProcessor.execute());
        System.out.println("Parallel result: " + parallelProcessor.execute());
    }

