public class ConcurrentSpellcasting {

    public interface Charm<T> {
        T invoke();
    }

    public static class RuneNode<T> {
        private final T value;
        private final List<RuneNode<T>> children;

        public RuneNode(T value, RuneNode<T>... children) {
            this.value = value;
            this.children = new ArrayList<>(Arrays.asList(children));
        }

        public T getValue() {
            return value;
        }

        public List<RuneNode<T>> getChildren() {
            return children;
        }
    }

    private static class SequentialCharmInvoker<T> implements Charm<T> {
        private final RuneNode<T> node;

        public SequentialCharmInvoker(RuneNode<T> node) {
            this.node = node;
        }

        @Override
        public T invoke() {
            return processSequentially(node);
        }

        private T processSequentially(RuneNode<T> node) {
            if (node == null || node.getChildren().isEmpty()) {
                return node.getValue();
            }

            for (RuneNode<T> child : node.getChildren()) {
                processSequentially(child);
            }

            return node.getValue();
        }
    }

    private static class ParallelCharmInvoker<T> implements Charm<T> {
        private final RuneNode<T> node;
        private final ExecutorService executor;

        public ParallelCharmInvoker(RuneNode<T> node) {
            this.node = node;
            this.executor = Executors.newFixedThreadPool(2);
        }

        @Override
        public T invoke() throws InterruptedException, ExecutionException {
            return processParallel(node, executor);
        }

        private T processParallel(RuneNode<T> node, ExecutorService executor)
                throws InterruptedException, ExecutionException {
            if (node == null || node.getChildren().isEmpty()) {
                return node.getValue();
            }

            List<Future<T>> futures = new ArrayList<>();
            for (RuneNode<T> child : node.getChildren()) {
                Charm<T> charm = new ParallelCharmInvoker<>(child);
                Future<T> future = executor.submit(charm);
                futures.add(future);
            }

            T value = node.getValue();
            for (Future<T> future : futures) {
                value = future.get();
            }

            return value;
        }
    }

    public static void main(String[] args) {
        RuneNode<Integer> runeTree = new RuneNode<>(1,
                new RuneNode<>(2,
                        new RuneNode<>(3),
                        new RuneNode<>(4)),
                new RuneNode<>(5,
                        new RuneNode<>(6),
                        new RuneNode<>(7)));

