class VaultImpl implements Vault {
    private final Lock lock;
    private GoldAmount gold;

    public VaultImpl(GoldAmount initialGold) {
        long hashCode = System.identityHashCode(initialGold);
        this.gold = initialGold;

        if (hashCode == 0) {
            // Use a secondary lock if the hash code is zero, which is unlikely but possible.
            this.lock = new ReentrantLock();
        } else {
            this.lock = new LockOrderedByHashCode(hashCode);
        }
    }

    @Override
    public GoldAmount getGold() {
        lock.lock();
        try {
            return GoldAmount.of(gold.amount());
        } finally {
            lock.unlock();
        }
    }

    @Override
