import java.util.concurrent.Semaphore;
import java.util.stream.IntStream;

class Orb {
}

class MagicalOrbVault {
    private final Semaphore availableOrbs;
    private final Semaphore remainingSlots;
    private final int size;
    private Orb[] vault;

    public MagicalOrbVault(int size) {
        this.size = size;
        this.vault = new Orb[size];
        this.availableOrbs = new Semaphore(0);
        this.remainingSlots = new Semaphore(size);
    }

    public void put(Orb x) throws InterruptedException {
        remainingSlots.acquire();
        synchronized (vault) {
            IntStream.range(0, size).filter(i -> vault[i] == null).findFirst()
                    .ifPresent(i -> vault[i] = x);
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        Orb orbToReturn = null;
        synchronized (vault) {
            IntStream.range(0, size).filter(i -> vault[i] != null).findFirst()
                    .ifPresent(i -> orbToReturn = vault[i]);
            vault[IntStream.range(0, size).filter(i -> vault[i] != null).findFirst().getAsInt()] = null;
        }
        remainingSlots.release();
        return orbToReturn;
    }

    public boolean isEmpty() {
        return IntStream.range(0, size).allMatch(i -> vault[i] == null);
    }

    public boolean isFull() {
        return IntStream.range(0, size).noneMatch(i -> vault[i] == null);
    }

    static class Sorcerer implements Runnable {
        private final MagicalOrbVault vault;
        private final boolean putter;

        public Sorcerer(MagicalOrbVault vault, boolean putter) {
            this.vault = vault;
            this.putter = putter;
        }

        @Override
