            try {
                if (putter) {
                    Orb orb = new Orb();
                    System.out.println("Sorcerer is putting an orb into the vault");
                    vault.put(orb);
                    System.out.println("Sorcerer has put an orb into the vault");
                } else {
                    System.out.println("Sorcerer is taking an orb from the vault");
                    Orb orb = vault.take();
                    System.out.println("Sorcerer has taken an orb from the vault");
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MagicalOrbVault vault = new MagicalOrbVault(5);

