class Potion {
    private final Semaphore slots;
    private final Semaphore potions;
    private int head = 0;
    private int tail = 0;
    private int size = 0;
    private final Object[] loop;

    public Potion(int capacity) {
        this.slots = new Semaphore(capacity);
        this.potions = new Semaphore(0);
        this.loop = new Object[capacity];
    }

    public void put(Object x) throws InterruptedException {
        slots.acquire();
        synchronized (loop) {
            while (isFull()) {
                loop.wait();
            }
            loop[head] = x;
            head = (head + 1) % loop.length;
            size++;
            loop.notifyAll();
        }
        potions.release();
    }

