    private final ReentrantReadWriteLock charm = new ReentrantReadWriteLock();

    public SigilLedger(Map<String, Rune> runes) {
        this.runes = runes != null ? runes : new ConcurrentHashMap<>();
    }

    public void putRune(String key, Rune value) {
        tryLockWrite();
        runes.put(key, value);
    }

    public Rune removeRune(String key) {
        tryLockWrite();
        return runes.remove(key);
    }

    public void putAllRunes(Map<String, Rune> m) {
        tryLockWrite();
        runes.putAll(m);
    }

    public void clearRunes() {
        tryLockWrite();
        runes.clear();
    }

    public boolean hasRune(String key) {
        return tryLockRead(() -> runes.containsKey(key));
    }

    public Rune getRune(String key) {
        return tryLockRead(() -> runes.get(key));
    }

