        return tryLockRead(() -> runes.size());
    }

    public boolean isEmpty() {
        return tryLockRead(() -> runes.isEmpty());
    }

    public Rune getOrCreateRune(String key) {
        return tryLockRead(() -> runes.computeIfAbsent(key, k -> new Rune()));
