import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Constellation<K, V> {
    private Map<K, V> stars;

    Constellation(Map<K, V> stars) {
        this.stars = new HashMap<>(stars);
    }

    Map<K, V> getStars() {
        return Collections.unmodifiableMap(stars);
    }
}

class MutableOrb {
    int shimmerX;
    int shimmerY;

    MutableOrb(int shimmerX, int shimmerY) {
        this.shimmerX = shimmerX;
        this.shimmerY = shimmerY;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MutableOrb)) return false;
        MutableOrb orb = (MutableOrb) o;
        return shimmerX == orb.shimmerX && shimmerY == orb.shimmerY;
    }

    @Override
    public int hashCode() {
        int result = shimmerX;
        result = 31 * result + shimmerY;
        return result;
    }
}

class ChronomanticDragonTracker {
    private Constellation<String, MutableOrb> constellation;

    ChronomanticDragonTracker(Constellation<String, MutableOrb> constellation) {
        this.constellation = deepClone(constellation);
    }

    private synchronized Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> constellation) {
        Map<String, MutableOrb> clonedStars = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : constellation.getStars().entrySet()) {
            clonedStars.put(entry.getKey(), new MutableOrb(entry.getValue().shimmerX, entry.getValue().shimmerY));
        }
        return new Constellation<>(clonedStars);
    }

    synchronized Constellation<String, MutableOrb> getConstellations() {
        return deepClone(constellation);
    }

    synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.getStars().get(sigil);
        return orb == null ? null : new MutableOrb(orb.shimmerX, orb.shimmerY);
    }

    synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (constellation.getStars().containsKey(sigil)) {
            constellation.getStars().put(sigil, new MutableOrb(shimmerX, shimmerY));
        } else {
            throw new IllegalArgumentException("Sigil not found");
        }
    }
}

class DragonTrackerTask implements Runnable {
    private ChronomanticDragonTracker tracker;
    private String sigil;
    private int newShimmerX;
    private int newShimmerY;

    public DragonTrackerTask(ChronomanticDragonTracker tracker, String sigil, int newShimmerX, int newShimmerY) {
        this.tracker = tracker;
        this.sigil = sigil;
        this.newShimmerX = newShimmerX;
        this.newShimmerY = newShimmerY;
    }

    @Override
    public void run() {
        Constellation<String, MutableOrb> constellationSnapshot = tracker.getConstellations();
        MutableOrb orb = tracker.getOrb(sigil);

        if (orb != null) {
            System.out.printf("Updating dragon with sigil %s from (%d, %d) to (%d, %d)%n", sigil, orb.shimmerX, orb.shimmerY, newShimmerX, newShimmerY);
        } else {
            System.out.printf("No dragon found with sigil %s%n", sigil);
        }

        tracker.setOrb(sigil, newShimmerX, newShimmerY);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Map<String, MutableOrb> initialConstellation = new HashMap<>();
        initialConstellation.put("dragon1", new MutableOrb(10, 20));
        initialConstellation.put("dragon2", new MutableOrb(30, 40));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(new Constellation<>(initialConstellation));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(new DragonTrackerTask(tracker, "dragon1", 50, 60));
        executor.execute(new DragonTrackerTask(tracker, "dragon3", 70, 80));

