import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Constellation<K, V> extends ConcurrentHashMap<K, V> {}
class MutableOrb {
    int shimmerX, shimmerY;
    public MutableOrb(int x, int y) { shimmerX = x; shimmerY = y; }
    public MutableOrb copy() { return new MutableOrb(shimmerX, shimmerY); }
}

class ChronomanticDragonTracker {
    private final Constellation<String, MutableOrb> constellation;

    ChronomanticDragonTracker(Constellation<String, MutableOrb> init) {
        this.constellation = new Constellation<>();
        init.forEach((sigil, orb) -> this.constellation.put(sigil, orb.copy()));
    }

    private static <K, V> Constellation<K, V> deepClone(Constellation<K, V> cons) {
        Constellation<K, V> newCons = new Constellation<>();
        cons.forEach((k, v) -> newCons.put(k, v));
        return newCons;
