import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class CelestialGriffinTracker {
    private final Map<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(StarlightMap<String, MutableGem> initialMap) {
        this.starlightMap = deepForge(initialMap);
    }

    synchronized void setGem(String rune, int glowX, int glowY) {
        if (!starlightMap.containsKey(rune)) {
            throw new IllegalArgumentException("Rune not found");
        }
        starlightMap.get(rune).setGlowX(glowX);
        starlightMap.get(rune).setGlowY(glowY);
    }

    synchronized MutableGem getGem(String rune) {
        return starlightMap.getOrDefault(rune, null);
    }

    synchronized Map<String, MutableGem> getStarlights() {
        return new HashMap<>(starlightMap);
    }

    private Map<String, MutableGem> deepForge(StarlightMap<String, MutableGem> initialMap) {
        Map<String, MutableGem> newMap = new HashMap<>();
        for (Map.Entry<String, MutableGem> entry : initialMap.entrySet()) {
            newMap.put(entry.getKey(), entry.getValue().copy());
        }
        return newMap;
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightMap<String, MutableGem> initialStarlightMap = new StarlightMap<>();
        CelestialGriffinTracker tracker = new CelestialGriffinTracker(initialStarlightMap);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 0; i < 10; i++) {
                tracker.setGem("runeA", i, i * 2);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 10; i++) {
                MutableGem gem = tracker.getGem("runeA");
                if (gem != null) {
                    System.out.println("runeA: glowX=" + gem.getGlowX() + ", glowY=" + gem.getGlowY());
                }
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        };

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, java.util.concurrent.TimeUnit.MILLISECONDS);
    }
}

