class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class Account {
    private final DollarAmount balance;
    private final ReentrantLock lock;

    public Account(DollarAmount initialBalance) {
        this.balance = initialBalance;
        this.lock = new ReentrantLock();
    }

    public DollarAmount getBalance() {
        return balance;
    }

    public boolean transfer(Account destination, DollarAmount amount, long timeout, TimeUnit unit) throws InterruptedException, InsufficientFundsException {
        if (!lock.tryLock(timeout, unit)) {
            return false;
        }
        try {
            if (balance.compareTo(amount) < 0) {
                throw new InsufficientFundsException("Insufficient funds.");
            }
            balance.subtract(amount);
            destination.deposit(amount);
            return true;
        } finally {
            lock.unlock();
        }
    }

    public void deposit(DollarAmount amount) {
        if (lock.isHeldByCurrentThread()) {
            balance.add(amount);
        } else {
            tryLockInterruptibly();
            try {
                balance.add(amount);
            } finally {
                unlock();
            }
        }
    }

    private void tryLockInterruptibly() throws InterruptedException {
        lock.tryLock(50, TimeUnit.MILLISECONDS);
    }

    private void unlock() {
        if (lock.isHeldByCurrentThread()) {
            lock.unlock();
        }
    }
