import java.math.BigInteger;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;

public class ConcurrentServlet extends HttpServlet {
    private volatile ImmutableCache cacheRef;

    public void init() throws ServletException {
        super.init();
        cacheRef = new ImmutableCache(computeValue(new BigInteger("0")));
    }

    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.setContentType("text/plain");
        PrintWriter out = response.getWriter();

        BigInteger inputValue = extractBigIntegerValue(request);
        BigInteger[] result = cacheRef.computeIfAbsent(inputValue, this::computeValue);

        if (result[0].equals(inputValue)) {
            out.println("Found in cache: " + result[0]);
        } else {
            out.println("Computed: " + result[0]);
        }
    }

    private BigInteger extractBigIntegerValue(HttpServletRequest request) {
        String param = request.getParameter("value");
        return new BigInteger(param);
    }

    private BigInteger[] computeValue(BigInteger value) {
        return new BigInteger[]{value};
    }

    static class ImmutableCache {
        private final BigInteger[] cachedResult;

        public ImmutableCache(BigInteger[] result) {
            this.cachedResult = result;
        }

        public BigInteger[] computeIfAbsent(BigInteger key, FunctionInterface function) {
            if (!Arrays.equals(cachedResult, new BigInteger[]{key})) {
                ExecutorService executor = Executors.newSingleThreadExecutor();
                BigInteger[] newResult = executor.submit(() -> function.apply(key)).get();
                cacheRef = new ImmutableCache(newResult);
            }
            return cachedResult;
        }
    }

    @FunctionalInterface
    interface FunctionInterface<R, T> {
        R apply(T t) throws Exception;
    }

    public static void main(String[] args) {
        HttpServer server = HttpServer.create(new InetSocketAddress("localhost", 8000), 0);
        server.createContext("/cache-servlet", new ConcurrentServlet());
        server.setExecutor(Executors.newSingleThreadExecutor());
        server.start();
    }
}

