    @Override
    public void run() {
        BigInteger[] factors = new BigInteger[0];
        if (num.mod(BigInteger.TWO).equals(BigInteger.ZERO)) {
            factors = new BigInteger[]{BigInteger.TWO, num.divide(BigInteger.TWO)};
        } else {
            for (int i = 3; i <= Math.sqrt(num.longValueExact()); i += 2) {
                if (num.mod(BigInteger.valueOf(i)).equals(BigInteger.ZERO)) {
                    factors = new BigInteger[]{BigInteger.valueOf(i), num.divide(BigInteger.valueOf(i))};
                    break;
                }
            }
        }
        if (factors[0] != null) {
            cache = new ImmutableCache(num, factors);
        }
    }

