import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Pattern;

class BetterAttributeStore {
    private final Map<String, String> attributeMap = new HashMap<>();

    public void put(String key, String value) {
        if (key == null || value == null) {
            throw new NullPointerException();
        }
        synchronized (this) {
            attributeMap.put(key, value);
        }
    }

    public boolean userLocationMatches(String name, String regexp) {
        Objects.requireNonNull(name, "Name cannot be null");
        Objects.requireNonNull(regexp, "Regexp cannot be null");

        return getAttributeValue("users." + name + ".location")
                .map(location -> Pattern.matches(regexp, location))
                .orElse(false);
    }

    private Optional<String> getAttributeValue(String key) {
        synchronized (this) {
            String value = attributeMap.get(key);
            return (value == null) ? Optional.empty() : Optional.of(value);
        }
    }
}

