class SimulatedCAS {
    private int value;

    public SimulatedCAS(int initialValue) {
        this.value = initialValue;
    }

    public synchronized int get() {
        return value;
    }

    public synchronized int compareAndSwap(int expectedValue, int newValue) {
        if (value == expectedValue) {
            value = newValue;
        }
        return expectedValue;
    }

    public synchronized boolean compareAndSet(int expectedValue, int newValue) {
        int currentValue = get();
        if (currentValue == expectedValue) {
            value = newValue;
            return true;
        } else {
            return false;
        }
    }
}

class Worker implements Runnable {
    private SimulatedCAS cas;
    private int times;
    private Random random;

    public Worker(SimulatedCAS cas, int times, Random random) {
        this.cas = cas;
        this.times = times;
        this.random = random;
    }

    @Override
    public void run() {
        for (int i = 0; i < times; i++) {
            int randomValue = random.nextInt(5);
            int originalValue = cas.compareAndSwap(i, randomValue);
            boolean success = cas.compareAndSet(originalValue, randomValue);
            if (success) {
                System.out.println("Updated successfully: " + originalValue + " -> " + randomValue);
            } else {
                System.out.println("Update failed.");
            }
        }
    }
}

