class Ark implements Runnable {
    private final BlockingQueue<Pair> pairsQueue;
    private int validPairsCount;

    public Ark(BlockingQueue<Pair> pairsQueue) {
        this.pairsQueue = pairsQueue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                Pair pair = pairsQueue.take();
                if (isValidPair(pair)) {
                    validPairsCount++;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private boolean isValidPair(Pair pair) {
        Animal animal1 = pair.getAnimal1();
        Animal animal2 = pair.getAnimal2();

        return animal1.getSpecies() == animal2.getSpecies() &&
                (animal1.getGender() != animal2.getGender());
    }

    public int getValidPairsCount() {
