    private static int loadTheArk(List<Animal> animals) {
        Comparator<Animal> comparator = (a1, a2) -> {
            int speciesCompare = Integer.compare(a1.getSpecies().ordinal(), a2.getSpecies().ordinal());
            if (speciesCompare == 0) {
                return Integer.compare(a1.getGender().ordinal(), a2.getGender().ordinal());
            } else {
                return speciesCompare;
            }
