    private static volatile boolean stopRequested;
    private static List<BigInteger> primes = new ArrayList<>();

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> {
            try {
                generatePrimes();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        TimeUnit.SECONDS.sleep(1);
        stopRequested = true;

        executor.shutdownNow();
        executor.awaitTermination(1, TimeUnit.SECONDS);

        System.out.println("Primes: " + primes);
    }

    private static void generatePrimes() throws InterruptedException {
        BigInteger candidate = BigInteger.TWO;

        while (!stopRequested && !isPrime(candidate)) {
            incrementCandidate(candidate);
        }

        if (isPrime(candidate)) {
            addAndPrintPrime(candidate);
        }

        while (!stopRequested && primes.size() < 10) {
            BigInteger nextCandidate = candidate.nextProbablePrime();

            if (isPrime(nextCandidate)) {
                addAndPrintPrime(nextCandidate);
            } else {
                candidate = nextCandidate;
            }
        }
    }

    private static void incrementCandidate(BigInteger current) {
        BigInteger newCandidate;

        do {
            current = current.add(BigInteger.ONE);
            newCandidate = current;
        } while (!isPrime(newCandidate));
    }

    private static void addAndPrintPrime(BigInteger prime) {
        synchronized (primes) {
            primes.add(prime);
            System.out.println("Added prime: " + prime);
        }
    }

    private static boolean isPrime(BigInteger num) {
        if (num.compareTo(BigInteger.TWO) < 0) {
            return false;
        } else if (num.equals(BigInteger.TWO)) {
            return true;
        } else {
            return num.mod(BigInteger.TWO).equals(BigInteger.ZERO);
        }
    }
}

