import java.math.BigInteger;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

class PrimeProducer extends Thread {
    private final BlockingQueue<BigInteger> queue;
    private volatile boolean running = true;

    public PrimeProducer(BlockingQueue<BigInteger> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        BigInteger prime = BigInteger.TWO;
        while (running) {
            try {
                queue.put(prime = prime.nextProbablePrime());
                if (queue.size() > 10) {
                    Thread.sleep(10);
                }
            } catch (InterruptedException e) {
                running = false;
            }
        }
    }

    public void requestStop() {
        this.running = false;
    }
}

class PrimeConsumer implements Runnable {
    private final BlockingQueue<BigInteger> queue;

    public PrimeConsumer(BlockingQueue<BigInteger> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                BigInteger prime = queue.take();
                System.out.println("Consumed prime: " + prime);
                if (queue.isEmpty()) {
                    break;
                }
            } catch (InterruptedException e) {
                // Consumer thread should exit when interrupted
                return;
            }
        }
    }
}

public class PrimeGenerator {

    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>(10);
        PrimeProducer producer = new PrimeProducer(queue);
        PrimeConsumer consumer = new PrimeConsumer(queue);

        producer.start();
        new Thread(consumer).start();

        // Wait for the consumer to finish
        new Thread(consumer).join();

        // Signal the producer to stop and wait for it to finish
        producer.requestStop();
        producer.join();
    }
}

