import java.math.BigInteger;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class PrimeProducer extends Thread {
private final BlockingQueue<BigInteger> queue;
private final int maxPrimesToGenerate;

public PrimeProducer(BlockingQueue<BigInteger> queue, int maxPrimesToGenerate) {
this.queue = queue;
this.maxPrimesToGenerate = maxPrimesToGenerate;
}

@Override
public void run() {
try {
BigInteger p = BigInteger.ONE;
int count = 0;
while (!Thread.currentThread().isInterrupted() && count < maxPrimesToGenerate) {
p = p.nextProbablePrime();
queue.put(p);
count++;
}
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
}

public void cancel() {
interrupt();
}

public static void main(String[] args) throws InterruptedException {
BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>();
final int primesToProduce = 2;

PrimeProducer producer = new PrimeProducer(queue, primesToProduce);
producer.start();

Thread consumer = new Thread(() -> {
int count = 0;
try {
while (count < primesToProduce) {
BigInteger prime = queue.take();
System.out.println("Consumed: " + prime);
count++;
}
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
System.out.println("Consumer was interrupted.");
}
});

consumer.start();
consumer.join();

producer.cancel();
producer.join();

System.out.println("All tasks completed.");
}
}

