        }

        @Override
        public Integer process() {
            return value;
        }
    }

    private static class RecursiveSequentialNode implements Node<Integer> {
        private final int value;
        private final List<Node<Integer>> children;

        public RecursiveSequentialNode(int value, Node<Integer>... nodes) {
            this.value = value;
            this.children = Arrays.asList(nodes);
        }

        @Override
        public List<Node<Integer>> getChildren() {
            return children;
        }

        @Override
        public Integer process() {
            int result = value;
            for (Node<Integer> child : children) {
                result += child.process();
            }
            return result;
        }
    }

    private static class RecursiveParallelNode implements Node<Integer> {
        private final int value;
        private final List<Node<Integer>> children;
        private final ExecutorService executor;

        public RecursiveParallelNode(int value, List<Node<Integer>> children, ExecutorService executor) {
            this.value = value;
            this.children = children;
            this.executor = executor;
        }

        @Override
        public List<Node<Integer>> getChildren() {
            return children;
        }

        @Override
        public Integer process() {
            List<Future<Integer>> futures = new ArrayList<>();
            for (Node<Integer> child : children) {
                Future<Integer> future = executor.submit(() -> child.process());
                futures.add(future);
            }

            int result = value;
            try {
                for (Future<Integer> future : futures) {
                    result += future.get();
                }
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }

            return result;
        }
    }

    private static <T> List<T> sequentialProcess(List<Node<T>> nodes) {
        List<T> results = new ArrayList<>();
        for (Node<T> node : nodes) {
            results.add(node.process());
        }
        return results;
    }

    private static <T> List<T> parallelProcess(List<Node<T>> nodes, ExecutorService executor) {
        List<Future<T>> futures = new ArrayList<>();
        for (Node<T> node : nodes) {
            Future<T> future = executor.submit(() -> node.process());
            futures.add(future);
        }

        List<T> results = new ArrayList<>();
        try {
            for (Future<T> future : futures) {
                results.add(future.get());
            }
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }
        return results;
    }

    private static ExecutorService createFixedThreadPool() {
        return Executors.newFixedThreadPool(2);
    }

    public static void main(String[] args) {
        SequentialNode sequential1 = new SequentialNode(1);
        SequentialNode sequential2 = new SequentialNode(2);
        RecursiveSequentialNode sequential3 = new RecursiveSequentialNode(3, sequential1, sequential2);

        List<Node<Integer>> sequentialNodes = Arrays.asList(sequential1, sequential2, sequential3);

        ExecutorService executor = createFixedThreadPool();
        RecursiveParallelNode parallel1 = new RecursiveParallelNode(1, sequentialNodes, executor);
        RecursiveParallelNode parallel2 = new RecursiveParallelNode(2, Arrays.asList(parallel1), executor);

        List<Node<Integer>> parallelNodes = Arrays.asList(parallel1, parallel2);

        List<Integer> sequentialResults = sequentialProcess(sequentialNodes);
        List<Integer> parallelResults = parallelProcess(parallelNodes, executor);

        System.out.println("Sequential results: " + sequentialResults);
        System.out.println("Parallel results: " + parallelResults);

        executor.shutdown();
    }
}

import java.util.*;
