@SuppressWarnings("unchecked")
public class ConcurrentProgram {

    public interface Element<T> {
        T process();
    }

    public interface Node<T> extends Element<T> {
        List<Node<T>> getChildren();
    }

    private static <T> CompletableFuture<T> processSequential(Element<T> element) {
        return CompletableFuture.supplyAsync(() -> element.process());
    }

    private static <T> CompletableFuture<T> processParallelSingleThreaded(Node<T> node) {
        List<CompletableFuture<T>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildren()) {
            futures.add(processSequential(child));
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply((Void v) -> node.process());
    }

    private static <T> CompleitableFuture<T> processParallelMultiThreaded(Node<T> node, int numThreads) {
        ExecutorService executor = Executors.newFixedThreadPool(numThreads);
        List<CompletableFuture<T>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildren()) {
            final Node<T> finalChild = child;
            futures.add(CompletableFuture.supplyAsync(() -> processSequential(finalChild).join(), executor));
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply((Void v) -> node.process())
                .whenComplete((result, exception) -> executor.shutdown());
    }

    public static void main(String[] args) {
        // Example usage of the methods provided above
        Element<Integer> element = new Element<Integer>() {
            @Override
            public Integer process() {
                return 0;
            }
        };

        Node<Integer> node = new Node<Integer>() {
            private List<Node<Integer>> children = Arrays.asList(
                    new Node<Integer>() {
                        @Override
                        public List<Node<Integer>> getChildren() {
                            return Collections.singletonList(element);
                        }

                        @Override
                        public Integer process() {
                            return 1;
                        }
                    },
                    new Node<Integer>() {
                        @Override
                        public List<Node<Integer>> getChildren() {
                            return Collections.singletonList(element);
                        }

                        @Override
                        public Integer process() {
                            return 2;
                        }
                    }
            );

            @Override
            public List<Node<Integer>> getChildren() {
                return children;
            }

            @Override
            public Integer process() {
                return 0;
            }
        };

        int numThreads = 2; // Change this value to test different number of threads

        CompletableFuture.supplyAsync(() -> processSequential(node).join())
                .thenAccept(result -> System.out.println("Sequential result: " + result));

        CompletableFuture.supplyAsync(() -> processParallelSingleThreaded(node).join())
                .thenAccept(result -> System.out.println("Parallel Single Threaded result: " + result));

        CompletableFuture.supplyAsync(() -> processParallelMultiThreaded(node, numThreads).join())
                .thenAccept(result -> System.out.println("Parallel Multi Threaded result with " + numThreads + " threads: " + result));
    }
}

import java.util.*;
import java.util.concurrent.*;

@SuppressWarnings("unchecked")
public class ConcurrentProgram {

    public static void main(String[] args) {
        Element element = new Node(42,
                Arrays.asList(
                        new Node(1),
                        new Node(2,
                                Arrays.asList(
                                        new Node(3),
                                        new Node(4)
                                )
                        ),
                        new Node(5)
                )
        );

        System.out.println("Sequential result: " + sequentialProcess((Node<Integer>) element));
        System.out.println("Parallel result: " + parallelProcess((Node<Integer>) element));
    }

    private static <T> int sequentialProcess(Node<T> node) {
        return node.compute(value -> (Integer) value);
    }

    private static <T> int parallelProcess(Node<T> node) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Collection<Future<Integer>> results = new ArrayList<>();

        results.add(executor.submit(() -> sequentialProcess(node)));

        for (Node<T> child : node.getChildren()) {
            results.add(executor.submit(() -> parallelProcess(child)));
        }

        int finalResult = 0;
        try {
            for (Future<Integer> result : results) {
                finalResult += result.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }

        executor.shutdown();

        return finalResult;
    }

    @FunctionalInterface
    public interface Element<T> {
        int compute(T value);
    }

    public static class Node<T> implements Element<T> {
        private T value;
        private List<Node<T>> children;

        public Node(T value) {
            this.value = value;
            this.children = new ArrayList<>();
        }

        public Node(T value, Collection<? extends Node<T>> children) {
            this.value = value;
            this.children.addAll(children);
        }

        @Override
        public int compute(T value) {
            this.value = value;
            return (Integer) value;
        }

        public Collection<Node<T>> getChildren() {
            return Collections.unmodifiableList(children);
        }

        public void addChild(Node<T> child) {
            children.add(child);
        }
    }
}

