    private final ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<String, String> map) {
        this.map = map;
    }

    public void put(String key, String value) {
        rwl.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public String get(String key) {
        rwl.readLock().lock();
